149	// decide performs the trial placement: among nodes whose labels contain every
150	// selector pair and whose capacity fits the request, it picks the name that is
151	// smallest in UTF-8 byte order. Capacity is only probed and never deducted.
152	func decide(p *store.Placement) (status string, node *string, reason *string) {
153		var chosen string
154		for i := range p.Nodes {
155			n := &p.Nodes[i]
156			if !labelsSatisfy(n.Labels, p.Selector) {
157				continue
158			}
159			if n.CPU < p.Resources.CPU || n.Memory < p.Resources.Memory {
160				continue
161			}
162			if chosen == "" || n.Name < chosen {
163				chosen = n.Name
164			}
165		}
166		if chosen != "" {
167			n := chosen
