215	func parsePlacement(body []byte) (*store.Placement, error) {
216		dec := json.NewDecoder(bytes.NewReader(body))
217		dec.UseNumber()
218	
219		tok, err := dec.Token()
220		if err != nil {
221			return nil, errInvalidPlacement
222		}
223		if d, ok := tok.(json.Delim); !ok || d != '{' {
224			return nil, errInvalidPlacement
225		}
226	
227		p := &store.Placement{}
228		seen := map[string]bool{}
229		for dec.More() {
230			keyTok, err := dec.Token()
231			if err != nil {
232				return nil, errInvalidPlacement
233			}
234			key, ok := keyTok.(string)
235			if !ok || !topLevelFields[key] || seen[key] {
236				return nil, errInvalidPlacement
237			}
238			seen[key] = true
239	
240			var raw json.RawMessage
241			if err := dec.Decode(&raw); err != nil {
242				return nil, errInvalidPlacement
243			}
244	
245			switch key {
246			case "namespace", "name", "queue":
247				s, err := parseTrimmedString(raw)
248				if err != nil {
249					return nil, err
250				}
251				switch key {
252				case "namespace":
253					p.Namespace = s
254				case "name":
255					p.Name = s
256				case "queue":
257					p.Queue = s
258				}
259			case "priority":
260				n, err := parseBoundedInt(raw, 32)
261				if err != nil {
262					return nil, err
263				}
264				p.Priority = int32(n)
265			case "resources":
266				r, err := parseResources(raw)
267				if err != nil {
268					return nil, err
269				}
270				p.Resources = r
271			case "selector":
272				m, err := parseStringMap(raw)
273				if err != nil {
274					return nil, err
275				}
276				p.Selector = m
277			case "nodes":
278				nodes, err := parseNodes(raw)
279				if err != nil {
280					return nil, err
281				}
282				p.Nodes = nodes
283			}
284		}
285		if _, err := dec.Token(); err != nil {
286			return nil, errInvalidPlacement // closing '}'
287		}
288		if _, err := dec.Token(); !errors.Is(err, io.EOF) {
289			return nil, errInvalidPlacement // trailing data
290		}
291	
292		for _, required := range []string{"namespace", "name", "queue", "priority", "resources", "nodes"} {
293			if !seen[required] {
294				return nil, errInvalidPlacement
295			}
296		}
297		if p.Selector == nil {
298			p.Selector = map[string]string{}
299		}
300		return p, nil
