318		if err != nil || cpu <= 0 {
319			return r, errInvalidPlacement
320		}
321		memory, err := parseBoundedInt(memoryRaw, 64)
322		if err != nil || memory <= 0 {
323			return r, errInvalidPlacement
324		}
