395	// parseStrictObject decodes an object whose member names are restricted to
396	// allowed. Both unknown and duplicate names are rejected.
397	func parseStrictObject(raw json.RawMessage, allowed map[string]bool) (map[string]json.RawMessage, error) {
398		if isNull(raw) {
399			return nil, errInvalidPlacement
400		}
401		dec := json.NewDecoder(bytes.NewReader(raw))
402		tok, err := dec.Token()
403		if err != nil {
404			return nil, errInvalidPlacement
405		}
406		if d, ok := tok.(json.Delim); !ok || d != '{' {
407			return nil, errInvalidPlacement
408		}
409		return readObjectMembers(dec, allowed)
410	}
411	
412	// parseStringMap decodes an object with arbitrary string keys and string
413	// values; null or non-string values are rejected.
414	func parseStringMap(raw json.RawMessage) (map[string]string, error) {
415		if isNull(raw) {
416			return nil, errInvalidPlacement
417		}
418		dec := json.NewDecoder(bytes.NewReader(raw))
419		tok, err := dec.Token()
420		if err != nil {
421			return nil, errInvalidPlacement
422		}
423		if d, ok := tok.(json.Delim); !ok || d != '{' {
424			return nil, errInvalidPlacement
425		}
426	
427		out := map[string]string{}
428		raws, err := readObjectMembers(dec, nil)
429		if err != nil {
430			return nil, err
431		}
432		for key, value := range raws {
433			s, err := parseJSONString(value)
434			if err != nil {
435				return nil, err
436			}
437			out[key] = s
438		}
439		return out, nil
440	}
441	
442	func readObjectMembers(dec *json.Decoder, allowed map[string]bool) (map[string]json.RawMessage, error) {
443		out := map[string]json.RawMessage{}
444		for dec.More() {
445			keyTok, err := dec.Token()
446			if err != nil {
447				return nil, errInvalidPlacement
448			}
449			key, ok := keyTok.(string)
450			if !ok {
451				return nil, errInvalidPlacement
452			}
453			if allowed != nil && !allowed[key] {
454				return nil, errInvalidPlacement
455			}
456			if _, dup := out[key]; dup {
457				return nil, errInvalidPlacement
458			}
459			var value json.RawMessage
460			if err := dec.Decode(&value); err != nil {
461				return nil, errInvalidPlacement
462			}
463			out[key] = value
464		}
465		if _, err := dec.Token(); err != nil {
466			return nil, errInvalidPlacement // closing '}'
467		}
468		return out, nil
469	}
470	
471	// parseTrimmedString accepts a JSON string that is non-empty and has no
472	// leading or trailing Unicode whitespace.
473	func parseTrimmedString(raw json.RawMessage) (string, error) {
474		s, err := parseJSONString(raw)
475		if err != nil {
476			return "", err
477		}
478		if s == "" || s != strings.TrimSpace(s) {
479			return "", errInvalidPlacement
480		}
481		return s, nil
482	}
483	
484	func parseJSONString(raw json.RawMessage) (string, error) {
485		if isNull(raw) {
486			return "", errInvalidPlacement
487		}
488		var s string
489		if err := json.Unmarshal(raw, &s); err != nil {
490			return "", errInvalidPlacement
491		}
492		return s, nil
493	}
494	
495	// parseBoundedInt accepts an integral JSON number without fraction or exponent
496	// that fits a signed integer of the given bit size (32 or 64).
497	func parseBoundedInt(raw json.RawMessage, bitSize int) (int64, error) {
498		if isNull(raw) {
499			return 0, errInvalidPlacement
500		}
501		dec := json.NewDecoder(bytes.NewReader(raw))
502		dec.UseNumber()
503		var value any
504		if err := dec.Decode(&value); err != nil {
505			return 0, errInvalidPlacement
506		}
507		number, ok := value.(json.Number)
508		if !ok {
509			return 0, errInvalidPlacement
510		}
511		n, err := strconv.ParseInt(number.String(), 10, bitSize)
512		if err != nil {
513			return 0, errInvalidPlacement
514		}
515		return n, nil
516	}
517	
518	func isNull(raw json.RawMessage) bool {
519		return bytes.Equal(bytes.TrimSpace(raw), []byte("null"))
520	}
